// The real-retailer catalog on the server: src/data/retail.json (generated by retailBuild.mjs from
// the research in catalog/retail/), read once from disk on first use. The client imports the same
// file as a lazy chunk; the server needs it for the brand lists (GET /api/catalog/brands?category=),
// to check a link-out click names a real product and store, and for Admin > Retailers.
//
// Nothing here calls a retailer. The admin's per-store settings (affiliate parameter, sponsored)
// and the click counts live in the `retailers` and `retail_clicks` tables (migrations/retail.mjs).

import fs from 'node:fs';
import { fileURLToPath } from 'node:url';

export const RETAIL_FILE = fileURLToPath(new URL('../../src/data/retail.json', import.meta.url));

/** Shared with the client (src/catalog/retail.ts): an affiliate parameter is a short query string. */
export const AFFILIATE_MAX = 200;
const AFFILIATE_RE = /^[A-Za-z0-9_.~-]{1,40}=[A-Za-z0-9_.~%-]{0,120}(&[A-Za-z0-9_.~-]{1,40}=[A-Za-z0-9_.~%-]{0,120}){0,4}$/;

/**
 * Normalises an admin's affiliate parameter: '' clears it; otherwise up to five `key=value` pairs
 * (a leading `?` is dropped). Returns null when it isn't one.
 */
export function cleanAffiliate(raw) {
  if (typeof raw !== 'string') return null;
  const s = raw.trim().replace(/^\?/, '');
  if (!s) return '';
  if (s.length > AFFILIATE_MAX || !AFFILIATE_RE.test(s)) return null;
  return s;
}

let cache = null;

/**
 * The parsed catalog with lookups. `file` is for tests; the default is src/data/retail.json.
 * A missing or unreadable file gives an empty catalog (logged once by the caller), never a crash.
 */
export function loadRetail(file = RETAIL_FILE) {
  if (cache && cache.file === file) return cache;
  let data;
  try {
    data = JSON.parse(fs.readFileSync(file, 'utf8'));
  } catch (err) {
    data = { version: 0, checkedAt: null, researched: 0, stores: [], products: [], leftOut: { count: 0, byReason: {} }, error: String(err?.message ?? err) };
  }
  const products = Array.isArray(data.products) ? data.products : [];
  const stores = Array.isArray(data.stores) ? data.stores : [];
  cache = {
    file,
    data,
    products,
    stores,
    storeBySlug: new Map(stores.map((s) => [s.slug, s])),
    byId: new Map(products.map((p) => [p.id, p])),
  };
  return cache;
}

/** Forget the cached file (tests that swap it). */
export function resetRetailCache() {
  cache = null;
}

/** True when `store` is one of the stores product `productId` is listed at. */
export function isListing(retail, productId, store) {
  const p = typeof productId === 'string' ? retail.byId.get(productId) : undefined;
  return !!p && typeof store === 'string' && p.retail.stores.some((l) => l.store === store);
}

/**
 * Retail brands with products in `category` (an app category id, or 'all'): product counts and the
 * stores that list them (most listings first). Most products first, then A–Z. BluModel Basics is
 * not here: the built-ins are compiled into the client, which adds them itself.
 */
export function brandsInCategory(retail, category) {
  const rows = new Map();
  for (const p of retail.products) {
    if (category !== 'all' && p.category !== category) continue;
    const r = rows.get(p.brand) ?? { brand: p.brand, products: 0, stores: new Map() };
    r.products += 1;
    for (const s of new Set(p.retail.stores.map((l) => l.store))) r.stores.set(s, (r.stores.get(s) ?? 0) + 1);
    rows.set(p.brand, r);
  }
  return [...rows.values()]
    .map((r) => {
      const slugs = [...r.stores].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0])).map(([s]) => s);
      return { brand: r.brand, products: r.products, stores: slugs.map((s) => retail.storeBySlug.get(s)?.name ?? s), storeSlugs: slugs };
    })
    .sort((a, b) => b.products - a.products || a.brand.localeCompare(b.brand));
}
